import customers from './customers.json' with {type:'json'};

const TOOLS = [
  {
    name: 'customer_lookup',
    description: 'Look up a customer by their unique customer id and return their details.',
    inputSchema: {
      type: 'object',
      properties: {
        customer_id: {
          type: 'string',
          description: 'The unique identifier of the customer to look up.',
        },
      },
      required: ['customer_id'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

function fail(message) {
  throw new Error(message);
}

function validateArguments(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    fail('Arguments must be an object');
  }
  const { customer_id, ...rest } = args;
  if (customer_id === undefined) {
    fail("Missing required argument: 'customer_id'");
  }
  if (typeof customer_id !== 'string') {
    fail("Argument 'customer_id' must be a string");
  }
  if (customer_id.length === 0) {
    fail("Argument 'customer_id' must not be empty");
  }
  if (Object.keys(rest).length > 0) {
    fail("Unknown argument(s): " + Object.keys(rest).join(', '));
  }
  return customer_id;
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    fail('Unknown tool: ' + name);
  }
  const customerId = validateArguments(args || {});
  const customer = customers[customerId];
  if (!customer) {
    fail('Unknown customer: ' + customerId);
  }
  return {
    content: [
      {
        type: 'text',
        text: `Name: ${customer.name}\nTier: ${customer.tier}`,
      },
    ],
  };
}

